#!/usr/bin/env bash
set -euo pipefail
name=""; tag=""; dir=""
usage() { echo "usage: $0 -n NAME [-t TAG] [-d DIR]" >&2; exit 1; }
while getopts ":n:t:d:" opt; do
  case "$opt" in
    n) name="$OPTARG" ;;
    t) tag="$OPTARG" ;;
    d) dir="$OPTARG" ;;
    *) usage ;;
  esac
done
[ -n "${name}" ] || usage
echo "name=${name} tag=${tag} dir=${dir}"
